window.officeBundle = {"date":"2026-11-17","services":{"morning_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"Let the words of my mouth and the meditation of my heart be always acceptable in your sight, O Lord, my rock and my redeemer."},{"line_type":"citation","content":"PSALM 19:14"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Venite"},{"line_type":"subheading","content":"O Come"},{"line_type":"rubric","content":"Officiant and People, all standing"},{"line_type":"leader","content":"Worship the Lord in the beauty of holiness:"},{"line_type":"congregation","content":"O come, let us adore him."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"O come, let us sing unto the Lord; *"},{"line_type":"congregation","content":"let us heartily rejoice in the strength of our salvation."},{"line_type":"congregation","content":"Let us come before his presence with thanksgiving *"},{"line_type":"congregation","content":"and show ourselves glad in him with psalms."},{"line_type":"congregation","content":"For the Lord is a great God *"},{"line_type":"congregation","content":"and a great King above all gods."},{"line_type":"congregation","content":"In his hand are all the depths of the earth, *"},{"line_type":"congregation","content":"and the heights of the hills are his also."},{"line_type":"congregation","content":"The sea is his, for he made it, *"},{"line_type":"congregation","content":"and his hands prepared the dry land."},{"line_type":"congregation","content":"O come, let us worship and fall down, *"},{"line_type":"congregation","content":"and kneel before the Lord our Maker."},{"line_type":"congregation","content":"For he is our God, *"},{"line_type":"congregation","content":"and we are the people of his pasture,"},{"line_type":"congregation","content":"and the sheep of his hand."},{"line_type":"rubric","content":"The following verses may be omitted."},{"line_type":"congregation","content":"Today, if you will hear his voice, harden not your hearts *"},{"line_type":"congregation","content":"as in the provocation, and as in the day of temptation in the wilderness,"},{"line_type":"congregation","content":"When your fathers tested me, *"},{"line_type":"congregation","content":"and put me to the proof, though they had seen my works."},{"line_type":"congregation","content":"Forty years long was I grieved with this generation and said, *"},{"line_type":"congregation","content":"\u201cIt is a people that err in their hearts, for they have not known my ways,\u201d"},{"line_type":"congregation","content":"Of whom I swore in my wrath *"},{"line_type":"congregation","content":"that they should not enter into my rest."},{"line_type":"citation","content":"Psalm 95:1-7, 8-11"},{"line_type":"leader","content":"Worship the Lord in the beauty of holiness:"},{"line_type":"congregation","content":"O come, let us adore him."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalm Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 45"},{"line_type":"subheading","content":"Eructavit cor meum"},{"line_type":"leader","content":"My heart overflows with a noble song; *","preface":1},{"line_type":"leader","content":"I will sing my words to the King; my tongue is the pen of a ready writer."},{"line_type":"congregation","content":"You are fairer than the children of men; *","preface":2},{"line_type":"congregation","content":"full of grace are your lips, because God has blessed you for ever."},{"line_type":"leader","content":"Gird your sword upon your thigh, most mighty one, *","preface":3},{"line_type":"leader","content":"according to your honor and majesty."},{"line_type":"congregation","content":"In your majesty be victorious; ride out for the sake of truth, to bear witness to righteousness, *","preface":4},{"line_type":"congregation","content":"and your right hand shall show you marvelous things."},{"line_type":"leader","content":"Your arrows are very sharp in the heart of the King\u2019s enemies, *","preface":5},{"line_type":"leader","content":"and the peoples shall be subdued under you."},{"line_type":"congregation","content":"Your throne, O God, endures for ever; *","preface":6},{"line_type":"congregation","content":"the scepter of your kingdom is a righteous scepter."},{"line_type":"leader","content":"You have loved righteousness and hated iniquity; *","preface":7},{"line_type":"leader","content":"therefore God, your God, has anointed you with the oil of gladness above your fellows."},{"line_type":"congregation","content":"All your garments smell of myrrh, aloes, and cassia; *","preface":8},{"line_type":"congregation","content":"out of the ivory palaces, stringed instruments have made you glad."},{"line_type":"leader","content":"Kings\u2019 daughters are among your honorable women; *","preface":9},{"line_type":"leader","content":"at your right hand stands the queen in a vesture of gold, wrought with many colors."},{"line_type":"congregation","content":"Hearken, O daughter, and consider; incline your ear; *","preface":10},{"line_type":"congregation","content":"forget your own people, and your father\u2019s house."},{"line_type":"leader","content":"So shall the King have pleasure in your beauty; *","preface":11},{"line_type":"leader","content":"since he is your Lord, honor him."},{"line_type":"congregation","content":"And the daughter of Tyre shall bring you gifts; *","preface":12},{"line_type":"congregation","content":"the rich also among the peoples shall seek your favor."},{"line_type":"leader","content":"The King\u2019s daughter is all glorious within the palace; *","preface":13},{"line_type":"leader","content":"her clothing is of wrought gold."},{"line_type":"congregation","content":"She shall be brought to the king in embroidered raiment; *","preface":14},{"line_type":"congregation","content":"the virgins who are her companions shall bring her to you."},{"line_type":"leader","content":"With joy and gladness shall they bring her, *","preface":15},{"line_type":"leader","content":"and shall enter into the King\u2019s palace."},{"line_type":"congregation","content":"Instead of your fathers, you shall have sons, *","preface":16},{"line_type":"congregation","content":"whom you shall make princes in all the land."},{"line_type":"leader","content":"I will make your Name to be remembered from one generation to another; *","preface":17},{"line_type":"leader","content":"therefore the peoples shall praise you, world without end."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Judith 11"},{"line_type":"reader","content":"A reading from the Book of Judith, beginning with the eleventh chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_5824a54f-8edf-51c5-bd32-32b36099289c'></span><p><span class=\"cc vnumVis\">11</span>Then said Holofernes unto her, Woman, be of good comfort, fear not in thine heart: for I never hurt any that was willing to serve Nabuchodonosor, the king of all the earth. <sup>2\u00a0</sup>Now therefore, if thy people that dwelleth in the mountains had not set light by me, I would not have lifted up my spear against them: but they have done these things to themselves. <sup>3\u00a0</sup>But now tell me wherefore thou art fled from them, and art come unto us: for thou art come for safeguard; be of good comfort, thou shalt live this night, and hereafter: <sup>4\u00a0</sup>For none shall hurt thee, but entreat thee well, as they do the servants of king Nabuchodonosor my lord. <sup>5\u00a0</sup>Then Judith said unto him, Receive the words of thy servant, and suffer thine handmaid to speak in thy presence, and I will declare no lie to my lord this night. <sup>6\u00a0</sup>And if thou wilt follow the words of thine handmaid, God will bring the thing perfectly to pass by thee; and my lord shall not fail of his purposes. <sup>7\u00a0</sup>As Nabuchodonosor king of all the earth liveth, and as his power liveth, who hath sent thee for the upholding of every living thing: for not only men shall serve him by thee, but also the beasts of the field, and the cattle, and the fowls of the air, shall live by thy power under Nabuchodonosor and all his house. <sup>8\u00a0</sup>For we have heard of thy wisdom and thy policies, and it is reported in all the earth, that thou only art excellent in all the kingdom, and mighty in knowledge, and wonderful in feats of war. <sup>9\u00a0</sup>Now as concerning the matter, which Achior did speak in thy council, we have heard his words; for the men of Bethulia saved him, and he declared unto them all that he had spoken unto thee. <sup>10\u00a0</sup>Therefore, O lord and governor, respect not his word; but lay it up in thine heart, for it is true: for our nation shall not be punished, neither can sword prevail against them, except they sin against their God. <sup>11\u00a0</sup>And now, that my lord be not defeated and frustrate of his purpose, even death is now fallen upon them, and their sin hath overtaken them, wherewith they will provoke their God to anger whensoever they shall do that which is not fit to be done: <sup>12\u00a0</sup>For their victuals fail them, and all their water is scant, and they have determined to lay hands upon their cattle, and purposed to consume all those things, that God hath forbidden them to eat by his laws: <sup>13\u00a0</sup>And are resolved to spend the firstfruits of the the tenths of wine and oil, which they had sanctified, and reserved for the priests that serve in Jerusalem before the face of our God; the which things it is not lawful for any of the people so much as to touch with their hands. <sup>14\u00a0</sup>For they have sent some to Jerusalem, because they also that dwell there have done the like, to bring them a licence from the senate. <sup>15\u00a0</sup>Now when they shall bring them word, they will forthwith do it, and they shall be given to thee to be destroyed the same day. <sup>16\u00a0</sup>Wherefore I thine handmaid, knowing all this, am fled from their presence; and God hath sent me to work things with thee, whereat all the earth shall be astonished, and whosoever shall hear it. <sup>17\u00a0</sup>For thy servant is religious, and serveth the God of heaven day and night: now therefore, my lord, I will remain with thee, and thy servant will go out by night into the valley, and I will pray unto God, and he will tell me when they have committed their sins: <sup>18\u00a0</sup>And I will come and shew it unto thee: then thou shalt go forth with all thine army, and there shall be none of them that shall resist thee. <sup>19\u00a0</sup>And I will lead thee through the midst of Judea, until thou come before Jerusalem; and I will set thy throne in the midst thereof; and thou shalt drive them as sheep that have no shepherd, and a dog shall not so much as open his mouth at thee: for these things were told me according to my foreknowledge, and they were declared unto me, and I am sent to tell thee. <sup>20\u00a0</sup>Then her words pleased Holofernes and all his servants; and they marvelled at her wisdom, and said, <sup>21\u00a0</sup>There is not such a woman from one end of the earth to the other, both for beauty of face, and wisdom of words. <sup>22\u00a0</sup>Likewise Holofernes said unto her. God hath done well to send thee before the people, that strength might be in our hands and destruction upon them that lightly regard my lord. <sup>23\u00a0</sup>And now thou art both beautiful in thy countenance, and witty in thy words: surely if thou do as thou hast spoken thy God shall be my God, and thou shalt dwell in the house of king Nabuchodonosor, and shalt be renowned through the whole earth.<br/></p>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"Here ends the Reading."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"TE DEUM LAUDAMUS"},{"line_type":"subheading","content":"We Praise You, O God"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"We praise you, O God; we acclaim you as Lord; *"},{"line_type":"congregation","content":"all creation worships you, the Father everlasting."},{"line_type":"congregation","content":"To you all angels, all the powers of heaven, *"},{"line_type":"congregation","content":"the cherubim and seraphim, sing in endless praise:"},{"line_type":"congregation","content":"Holy, Holy, Holy, Lord God of power and might, *"},{"line_type":"congregation","content":"heaven and earth are full of your glory."},{"line_type":"congregation","content":"The glorious company of apostles praise you. *"},{"line_type":"congregation","content":"The noble fellowship of prophets praise you."},{"line_type":"congregation","content":"The white-robed army of martyrs praise you. *"},{"line_type":"congregation","content":"Throughout the world the holy Church acclaims you:"},{"line_type":"congregation","content":"Father, of majesty unbounded,"},{"line_type":"congregation","content":"your true and only Son, worthy of all praise, *"},{"line_type":"congregation","content":"and the Holy Spirit, advocate and guide."},{"line_type":"congregation","content":"You, Christ, are the king of glory, *"},{"line_type":"congregation","content":"the eternal Son of the Father."},{"line_type":"congregation","content":"When you took our flesh to set us free *"},{"line_type":"congregation","content":"you humbly chose the Virgin\u2019s womb."},{"line_type":"congregation","content":"You overcame the sting of death *"},{"line_type":"congregation","content":"and opened the kingdom of heaven to all believers."},{"line_type":"congregation","content":"You are seated at God\u2019s right hand in glory. *"},{"line_type":"congregation","content":"We believe that you will come to be our judge."},{"line_type":"congregation","content":"Come then, Lord, and help your people, *"},{"line_type":"congregation","content":"bought with the price of your own blood,"},{"line_type":"congregation","content":"and bring us with your saints *"},{"line_type":"congregation","content":"to glory everlasting."},{"line_type":"rubric","content":"The following verses may be omitted"},{"line_type":"congregation","content":"Save your people, Lord, and bless your inheritance;*"},{"line_type":"congregation","content":"govern and uphold them now and always."},{"line_type":"congregation","content":"Day by day we bless you; *"},{"line_type":"congregation","content":"we praise your Name for ever."},{"line_type":"congregation","content":"Keep us today, Lord, from all sin; *"},{"line_type":"congregation","content":"have mercy on us, Lord, have mercy."},{"line_type":"congregation","content":"Lord, show us your love and mercy, *"},{"line_type":"congregation","content":"for we have put our trust in you."},{"line_type":"congregation","content":"In you, Lord, is our hope; *"},{"line_type":"congregation","content":"let us never be put to shame."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Acts 17:1-15"},{"line_type":"reader","content":"A reading from the Acts of the Apostles, beginning with the seventeenth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_7d63a585-ab3a-56bd-a95b-e57fd7db829c'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p class=\"top-1 chapter-2\"><span class=\"text Acts-17-1\" id=\"en-AKJV-27525\"><span class=\"chapternum\">17\u00a0</span>Now when they had passed through Amphipolis and Apollonia, they came to Thessalonica, where was a synagogue of the Jews: </span> <span class=\"text Acts-17-2\" id=\"en-AKJV-27526\"><sup class=\"versenum\">2\u00a0</sup>and Paul, as his manner was, went in unto them, and three sabbath days reasoned with them out of the scriptures, </span> <span class=\"text Acts-17-3\" id=\"en-AKJV-27527\"><sup class=\"versenum\">3\u00a0</sup>opening and alleging, that Christ must needs have suffered, and risen again from the dead; and that this Jesus, whom I preach unto you, is Christ. </span> <span class=\"text Acts-17-4\" id=\"en-AKJV-27528\"><sup class=\"versenum\">4\u00a0</sup>And some of them believed, and consorted with Paul and Silas; and of the devout Greeks a great multitude, and of the chief women not a few.</span></p><span data-line-id='secondreading_f937da60-b110-5411-a488-a2cec2dfdec5'></span> <p><span class=\"text Acts-17-5\" id=\"en-AKJV-27529\"><sup class=\"versenum\">5\u00a0</sup>But the Jews which believed not, moved with envy, took unto them certain lewd fellows of the baser sort, and gathered a company, and set all the city on an uproar, and assaulted the house of Jason, and sought to bring them out to the people. </span> <span class=\"text Acts-17-6\" id=\"en-AKJV-27530\"><sup class=\"versenum\">6\u00a0</sup>And when they found them not, they drew Jason and certain brethren unto the rulers of the city, crying, These that have turned the world upside down are come hither also; </span> <span class=\"text Acts-17-7\" id=\"en-AKJV-27531\"><sup class=\"versenum\">7\u00a0</sup>whom Jason hath received: and these all do contrary to the decrees of C\u00e6sar, saying that there is another king, one Jesus. </span> <span class=\"text Acts-17-8\" id=\"en-AKJV-27532\"><sup class=\"versenum\">8\u00a0</sup>And they troubled the people and the rulers of the city, when they heard these things. </span> <span class=\"text Acts-17-9\" id=\"en-AKJV-27533\"><sup class=\"versenum\">9\u00a0</sup>And when they had taken security of Jason, and of the other, they let them go.</span></p><span data-line-id='secondreading_a7aa42ab-0887-5fd3-a82a-5848946fcb1b'></span> <p><span class=\"text Acts-17-10\" id=\"en-AKJV-27534\"><sup class=\"versenum\">10\u00a0</sup>And the brethren immediately sent away Paul and Silas by night unto Berea: who coming thither went into the synagogue of the Jews. </span> <span class=\"text Acts-17-11\" id=\"en-AKJV-27535\"><sup class=\"versenum\">11\u00a0</sup>These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so. </span> <span class=\"text Acts-17-12\" id=\"en-AKJV-27536\"><sup class=\"versenum\">12\u00a0</sup>Therefore many of them believed; also of honourable women which were Greeks, and of men, not a few. </span> <span class=\"text Acts-17-13\" id=\"en-AKJV-27537\"><sup class=\"versenum\">13\u00a0</sup>But when the Jews of Thessalonica had knowledge that the word of God was preached of Paul at Berea, they came thither also, and stirred up the people. </span> <span class=\"text Acts-17-14\" id=\"en-AKJV-27538\"><sup class=\"versenum\">14\u00a0</sup>And then immediately the brethren sent away Paul to go as it were to the sea: but Silas and Timotheus abode there still. </span> <span class=\"text Acts-17-15\" id=\"en-AKJV-27539\"><sup class=\"versenum\">15\u00a0</sup>And they that conducted Paul brought him unto Athens: and receiving a commandment unto Silas and Timotheus for to come to him with all speed, they departed.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"BENEDICTUS"},{"line_type":"subheading","content":"The Song of Zechariah"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Blessed be the Lord, the God of Israel; *"},{"line_type":"congregation","content":"he has come to his people and set them free."},{"line_type":"congregation","content":"He has raised up for us a mighty savior, *"},{"line_type":"congregation","content":"born of the house of his servant David."},{"line_type":"congregation","content":"Through his holy prophets he promised of old"},{"line_type":"congregation","content":"that he would save us from our enemies, *"},{"line_type":"congregation","content":"from the hands of all who hate us."},{"line_type":"congregation","content":"He promised to show mercy to our fathers *"},{"line_type":"congregation","content":"and to remember his holy covenant."},{"line_type":"congregation","content":"This was the oath he swore to our father Abraham, *"},{"line_type":"congregation","content":"to set us free from the hands of our enemies,"},{"line_type":"congregation","content":"Free to worship him without fear, *"},{"line_type":"congregation","content":"holy and righteous in his sight"},{"line_type":"congregation","content":"all the days of our life."},{"line_type":"congregation","content":"You, my child, shall be called the prophet of the Most High, *"},{"line_type":"congregation","content":"for you will go before the Lord to prepare his way,"},{"line_type":"congregation","content":"To give his people knowledge of salvation *"},{"line_type":"congregation","content":"by the forgiveness of their sins."},{"line_type":"congregation","content":"In the tender compassion of our God *"},{"line_type":"congregation","content":"the dawn from on high shall break upon us,"},{"line_type":"congregation","content":"To shine on those who dwell in darkness"},{"line_type":"congregation","content":"and in the shadow of death, *"},{"line_type":"congregation","content":"and to guide our feet into the way of peace."},{"line_type":"citation","content":"LUKE 1:68-79"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Tuesday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Hugh, Bishop of Lincoln and Renewer of Society, 1200"},{"line_type":"leader","content":"O God, our heavenly Father, you raised up your faithful servant Hugh of Lincoln to be Bishop and pastor in your Church and to feed your flock: Give abundantly to all pastors the gifts of your Holy Spirit, that they may minister in your household as true servants of Christ and stewards of your divine mysteries; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Peace"},{"line_type":"subheading","content":"Tuesday"},{"line_type":"leader","content":"O God, the author of peace and lover of concord, to know you is eternal life and to serve you is perfect freedom: Defend us, your humble servants, in all assaults of our enemies; that we, surely trusting in your defense, may not fear the power of any adversaries, through the might of Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"Almighty and everlasting God, who alone works great marvels: Send down upon our clergy and the congregations committed to their charge the life-giving Spirit of your grace, shower them with the continual dew of your blessing, and ignite in them a zealous love of your Gospel; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Glory to God whose power, working in us, can do infinitely more than we can ask or imagine: Glory to him from generation to generation in the Church, and in Christ Jesus for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"EPHESIANS 3:20-21"}]}],"midday_prayer":[{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 119:105-112"},{"line_type":"subheading","content":"Beati immaculati"},{"line_type":"leader","content":"Your word is a lantern to my feet *","preface":105},{"line_type":"leader","content":"and a light upon my path."},{"line_type":"congregation","content":"I have sworn and am steadfastly purposed *","preface":106},{"line_type":"congregation","content":"to keep your righteous judgments."},{"line_type":"leader","content":"I am troubled above measure; *","preface":107},{"line_type":"leader","content":"revive me, O L\u1d0f\u0280\u1d05, according to your word."},{"line_type":"congregation","content":"Let the freewill offerings of my mouth please you, O L\u1d0f\u0280\u1d05; *","preface":108},{"line_type":"congregation","content":"and teach me your judgments."},{"line_type":"leader","content":"My life is always in my hand, *","preface":109},{"line_type":"leader","content":"yet I do not forget your law."},{"line_type":"congregation","content":"The ungodly have laid a snare for me, *","preface":110},{"line_type":"congregation","content":"yet I have not strayed from your commandments."},{"line_type":"leader","content":"Your testimonies have I claimed as my heritage for ever, *","preface":111},{"line_type":"leader","content":"and why? They are the very joy of my heart."},{"line_type":"congregation","content":"I have applied my heart to fulfill your statutes always, *","preface":112},{"line_type":"congregation","content":"even unto the end. Samekh"},{"line_type":"heading","content":"Psalm 121"},{"line_type":"subheading","content":"Levavi oculos"},{"line_type":"leader","content":"I will lift up my eyes unto the hills; *","preface":1},{"line_type":"leader","content":"from whence comes my help?"},{"line_type":"congregation","content":"My help comes from the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"who has made heaven and earth."},{"line_type":"leader","content":"He will not let your foot be moved, *","preface":3},{"line_type":"leader","content":"and he who keeps you will not sleep."},{"line_type":"congregation","content":"Behold, he who keeps Israel *","preface":4},{"line_type":"congregation","content":"shall neither slumber nor sleep."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 himself is your keeper; *","preface":5},{"line_type":"leader","content":"the L\u1d0f\u0280\u1d05 is your defense upon your right hand,"},{"line_type":"congregation","content":"So that the sun shall not burn you by day, *","preface":6},{"line_type":"congregation","content":"neither the moon by night."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 shall preserve you from all evil; *","preface":7},{"line_type":"leader","content":"indeed, it is he who shall keep your soul."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 shall preserve your going out and your coming in, *","preface":8},{"line_type":"congregation","content":"from this time forth for evermore."},{"line_type":"heading","content":"Psalm 124"},{"line_type":"subheading","content":"Nisi quia Dominus"},{"line_type":"leader","content":"If the L\u1d0f\u0280\u1d05 himself had not been on our side, now may Israel say: *","preface":1},{"line_type":"leader","content":"if the L\u1d0f\u0280\u1d05 himself had not been on our side, when men rose up against us,"},{"line_type":"congregation","content":"Then would they have swallowed us up alive, *","preface":2},{"line_type":"congregation","content":"when they were so wrathfully displeased with us;"},{"line_type":"leader","content":"Then the waters would have drowned us, and the torrent gone over us; *","preface":3},{"line_type":"leader","content":"then the raging waters would have gone clean over us."},{"line_type":"congregation","content":"But praised be the L\u1d0f\u0280\u1d05, *","preface":4},{"line_type":"congregation","content":"who has not given us over to be prey for their teeth."},{"line_type":"leader","content":"We escaped like a bird out of the snare of the fowler; *","preface":5},{"line_type":"leader","content":"the snare is broken, and we have been delivered."},{"line_type":"congregation","content":"Our help is in the Name of the L\u1d0f\u0280\u1d05, *","preface":6},{"line_type":"congregation","content":"the maker of heaven and earth."},{"line_type":"heading","content":"Psalm 126"},{"line_type":"subheading","content":"In convertendo"},{"line_type":"leader","content":"When the L\u1d0f\u0280\u1d05 overturned the captivity of Zion, *","preface":1},{"line_type":"leader","content":"then were we like those who dream."},{"line_type":"congregation","content":"Then was our mouth filled with laughter *","preface":2},{"line_type":"congregation","content":"and our tongue with shouts of joy."},{"line_type":"leader","content":"Then they said among the nations, *","preface":3},{"line_type":"leader","content":"\u201cThe L\u1d0f\u0280\u1d05 has done great things for them.\u201d"},{"line_type":"congregation","content":"Indeed, the L\u1d0f\u0280\u1d05 has done great things for us already, *","preface":4},{"line_type":"congregation","content":"whereof we rejoice."},{"line_type":"leader","content":"Overturn our captivity, O L\u1d0f\u0280\u1d05, *","preface":5},{"line_type":"leader","content":"as when streams refresh the deserts of the south."},{"line_type":"congregation","content":"Those who sow in tears *","preface":6},{"line_type":"congregation","content":"shall reap with songs of joy."},{"line_type":"leader","content":"He who goes on his way weeping and bears good seed *","preface":7},{"line_type":"leader","content":"shall doubtless come again with joy, and bring his sheaves with him."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"If anyone is in Christ, he is a new creation. The old has passed away; behold, the new has come. All this is from God, who through Christ reconciled us to himself and gave us the ministry of reconciliation."},{"line_type":"citation","content":"2 CORINTHIANS 5:17-18"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"A meditation, silent or spoken, may follow."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"I will bless the Lord at all times."},{"line_type":"congregation_dialogue","content":"His praise shall continually be in my mouth."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Blessed Savior, at this hour you hung upon the Cross, stretching out your loving arms: Grant that all the peoples of the earth may look to you and be saved; for your tender mercies\u2019 sake."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Almighty Savior, who at mid-day called your servant Saint Paul to be an apostle to the Gentiles: We pray you to illumine the world with the radiance of your glory, that all nations may come and worship you; for you live and reign with the Father and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."}]}],"evening_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"Lord, I have loved the habitation of your house and the place where your honor dwells."},{"line_type":"citation","content":"PSALM 26:8"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"PHOS HILARON"},{"line_type":"subheading","content":"O Gladsome Light"},{"line_type":"congregation","content":"O gladsome light,"},{"line_type":"congregation","content":"pure brightness of the everliving Father in heaven, *"},{"line_type":"congregation","content":"O Jesus Christ, holy and blessed!"},{"line_type":"congregation","content":"Now as we come to the setting of the sun,"},{"line_type":"congregation","content":"and our eyes behold the vesper light, *"},{"line_type":"congregation","content":"we sing your praises, O God: Father, Son, and Holy Spirit."},{"line_type":"congregation","content":"You are worthy at all times to be praised by happy voices, *"},{"line_type":"congregation","content":"O Son of God, O Giver of Life,"},{"line_type":"congregation","content":"and to be glorified through all the worlds."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalm Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 46"},{"line_type":"subheading","content":"Deus noster refugium"},{"line_type":"leader","content":"God is our refuge and strength, *","preface":1},{"line_type":"leader","content":"a very present help in trouble."},{"line_type":"congregation","content":"Therefore we will not fear, though the earth be moved, *","preface":2},{"line_type":"congregation","content":"and though the hills be carried into the midst of the sea;"},{"line_type":"leader","content":"Though its waters rage and swell, *","preface":3},{"line_type":"leader","content":"and though the mountains shake at its tempest."},{"line_type":"congregation","content":"There is a river whose streams make glad the city of God, *","preface":4},{"line_type":"congregation","content":"the holy dwelling place of the Most High."},{"line_type":"leader","content":"God is in the midst of her; therefore she shall not be moved. *","preface":5},{"line_type":"leader","content":"God shall help her at the break of day."},{"line_type":"congregation","content":"The nations are in an uproar, and the kingdoms are moved, *","preface":6},{"line_type":"congregation","content":"but God has lifted his voice, and the earth shall melt away."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 of hosts is with us; *","preface":7},{"line_type":"leader","content":"the God of Jacob is our refuge."},{"line_type":"congregation","content":"O come and behold the works of the L\u1d0f\u0280\u1d05, *","preface":8},{"line_type":"congregation","content":"what devastations he has brought upon the earth."},{"line_type":"leader","content":"He makes wars to cease in all the world; *","preface":9},{"line_type":"leader","content":"he breaks the bow, and shatters the spear, and burns the chariots in the fire."},{"line_type":"congregation","content":"\u201cBe still then and know that I am God; *","preface":10},{"line_type":"congregation","content":"I will be exalted among the nations, and I will be exalted in the earth.\u201d"},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 of hosts is with us; *","preface":11},{"line_type":"leader","content":"the God of Jacob is our refuge."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Isaiah 30"},{"line_type":"reader","content":"A reading from the Prophet Isaiah, beginning with the thirtieth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_776af11f-0fdd-5fc4-bf0c-a0711ede7511'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<div class=\"poetry top-1\"><p class=\"line\"><span class=\"chapter-2\"><span class=\"text Isa-30-1\" id=\"en-AKJV-18219\"><span class=\"chapternum\">30\u00a0</span>Woe to the rebellious children, saith the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>,</span></span><br/><span class=\"text Isa-30-1\">that take counsel, but not of me;</span><br/><span class=\"text Isa-30-1\">and that cover with a covering, but not of my spirit,</span><br/><span class=\"text Isa-30-1\">that they may add sin to sin:</span><br/><span class=\"text Isa-30-2\" id=\"en-AKJV-18220\"><sup class=\"versenum\">2\u00a0</sup>that walk to go down into Egypt,</span><br/><span class=\"text Isa-30-2\">and have not asked at my mouth;</span><br/><span class=\"text Isa-30-2\">to strengthen themselves in the strength of Pharaoh,</span><br/><span class=\"text Isa-30-2\">and to trust in the shadow of Egypt!</span><br/><span class=\"text Isa-30-3\" id=\"en-AKJV-18221\"><sup class=\"versenum\">3\u00a0</sup>Therefore shall the strength of Pharaoh be your shame,</span><br/><span class=\"text Isa-30-3\">and the trust in the shadow of Egypt your confusion.</span><br/><span class=\"text Isa-30-4\" id=\"en-AKJV-18222\"><sup class=\"versenum\">4\u00a0</sup>For his princes were at Zoan,</span><br/><span class=\"text Isa-30-4\">and his ambassadors came to Hanes.</span><br/><span class=\"text Isa-30-5\" id=\"en-AKJV-18223\"><sup class=\"versenum\">5\u00a0</sup>They were all ashamed of a people that could not profit them,</span><br/><span class=\"text Isa-30-5\">nor be an help nor profit,</span><br/><span class=\"text Isa-30-5\">but a shame, and also a reproach.</span></p><span data-line-id='firstreading_e5d14e6c-435f-5a81-8a73-9f3d5543f5f2'></span></div> <p class=\"first-line-none top-1\"><span class=\"text Isa-30-6\" id=\"en-AKJV-18224\"><sup class=\"versenum\">6\u00a0</sup>The burden of the beasts of the south:</span></p><span data-line-id='firstreading_7f18e3d0-1ff3-5fe3-8bd8-5fc81383a9d4'></span><div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-30-6\">into the land of trouble and anguish,</span><br/><span class=\"text Isa-30-6\">from whence come the young and old lion,</span><br/><span class=\"text Isa-30-6\">the viper and fiery flying serpent,</span><br/><span class=\"text Isa-30-6\">they will carry their riches upon the shoulders of young asses,</span><br/><span class=\"text Isa-30-6\">and their treasures upon the bunches of camels,</span><br/><span class=\"text Isa-30-6\">to a people that shall not profit them.</span><br/><span class=\"text Isa-30-7\" id=\"en-AKJV-18225\"><sup class=\"versenum\">7\u00a0</sup>For the Egyptians shall help in vain, and to no purpose:</span><br/><span class=\"text Isa-30-7\">therefore have I cried concerning this,</span><br/><span class=\"text Isa-30-7\">Their strength is to sit still.</span></p><span data-line-id='firstreading_0e717f18-371a-54fb-88e9-095fe9da0e10'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-30-8\" id=\"en-AKJV-18226\"><sup class=\"versenum\">8\u00a0</sup>Now go, write it before them in a table, and note it in a book,</span><br/><span class=\"text Isa-30-8\">that it may be for the time to come for ever and ever:</span><br/><span class=\"text Isa-30-9\" id=\"en-AKJV-18227\"><sup class=\"versenum\">9\u00a0</sup>that this is a rebellious people, lying children,</span><br/><span class=\"text Isa-30-9\">children that will not hear the law of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>:</span><br/><span class=\"text Isa-30-10\" id=\"en-AKJV-18228\"><sup class=\"versenum\">10\u00a0</sup>which say to the seers, See not;</span><br/><span class=\"text Isa-30-10\">and to the prophets, Prophesy not unto us right things,</span><br/><span class=\"text Isa-30-10\">speak unto us smooth things,</span><br/><span class=\"text Isa-30-10\">prophesy deceits:</span><br/><span class=\"text Isa-30-11\" id=\"en-AKJV-18229\"><sup class=\"versenum\">11\u00a0</sup>get you out of the way,</span><br/><span class=\"text Isa-30-11\">turn aside out of the path,</span><br/><span class=\"text Isa-30-11\">cause the Holy One of Israel to cease from before us.</span><br/><span class=\"text Isa-30-12\" id=\"en-AKJV-18230\"><sup class=\"versenum\">12\u00a0</sup>Wherefore thus saith the Holy One of Israel,</span><br/><span class=\"text Isa-30-12\">Because ye despise this word,</span><br/><span class=\"text Isa-30-12\">and trust in oppression and perverseness,</span><br/><span class=\"text Isa-30-12\">and stay thereon:</span><br/><span class=\"text Isa-30-13\" id=\"en-AKJV-18231\"><sup class=\"versenum\">13\u00a0</sup>therefore this iniquity shall be to you as a breach ready to fall,</span><br/><span class=\"text Isa-30-13\">swelling out in a high wall,</span><br/><span class=\"text Isa-30-13\">whose breaking cometh suddenly at an instant.</span><br/><span class=\"text Isa-30-14\" id=\"en-AKJV-18232\"><sup class=\"versenum\">14\u00a0</sup>And he shall break it as the breaking of the potters\u2019 vessel that is broken in pieces;</span><br/><span class=\"text Isa-30-14\">he shall not spare:</span><br/><span class=\"text Isa-30-14\">so that there shall not be found in the bursting of it</span><br/><span class=\"text Isa-30-14\">a sherd to take fire from the hearth,</span><br/><span class=\"text Isa-30-14\">or to take water withal out of the pit.</span><br/><span class=\"text Isa-30-15\" id=\"en-AKJV-18233\"><sup class=\"versenum\">15\u00a0</sup>For thus saith the Lord <span class=\"small-caps\" style=\"font-variant: small-caps\">God</span>, the Holy One of Israel;</span><br/><span class=\"text Isa-30-15\">In returning and rest shall ye be saved;</span><br/><span class=\"text Isa-30-15\">in quietness and in confidence shall be your strength:</span><br/><span class=\"text Isa-30-15\">and ye would not.</span><br/><span class=\"text Isa-30-16\" id=\"en-AKJV-18234\"><sup class=\"versenum\">16\u00a0</sup>But ye said, No; for we will flee upon horses;</span><br/><span class=\"text Isa-30-16\">therefore shall ye flee:</span><br/><span class=\"text Isa-30-16\">and, We will ride upon the swift;</span><br/><span class=\"text Isa-30-16\">therefore shall they that pursue you be swift.</span><br/><span class=\"text Isa-30-17\" id=\"en-AKJV-18235\"><sup class=\"versenum\">17\u00a0</sup>One thousand shall flee at the rebuke of one;</span><br/><span class=\"text Isa-30-17\">at the rebuke of five shall ye flee:</span><br/><span class=\"text Isa-30-17\">till ye be left as a beacon upon the top of a mountain,</span><br/><span class=\"text Isa-30-17\">and as an ensign on an hill.</span></p><span data-line-id='firstreading_3fb0d93d-468c-5eb8-8d59-1510b1496e33'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-30-18\" id=\"en-AKJV-18236\"><sup class=\"versenum\">18\u00a0</sup>And therefore will the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> wait,</span><br/><span class=\"text Isa-30-18\">that he may be gracious unto you,</span><br/><span class=\"text Isa-30-18\">and therefore will he be exalted,</span><br/><span class=\"text Isa-30-18\">that he may have mercy upon you:</span><br/><span class=\"text Isa-30-18\">for the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> is a God of judgment:</span><br/><span class=\"text Isa-30-18\">blessed are all they that wait for him.</span></p><span data-line-id='firstreading_addd0bf2-6d46-5b6f-9636-b2925af0ee04'></span></div> <p class=\"first-line-none top-1\"><span class=\"text Isa-30-19\" id=\"en-AKJV-18237\"><sup class=\"versenum\">19\u00a0</sup>For the people shall dwell in Zion at Jerusalem: thou shalt weep no more: he will be very gracious unto thee at the voice of thy cry; when he shall hear it, he will answer thee. </span> <span class=\"text Isa-30-20\" id=\"en-AKJV-18238\"><sup class=\"versenum\">20\u00a0</sup>And though the Lord give you the bread of adversity, and the water of affliction, yet shall not thy teachers be removed into a corner any more, but thine eyes shall see thy teachers: </span> <span class=\"text Isa-30-21\" id=\"en-AKJV-18239\"><sup class=\"versenum\">21\u00a0</sup>and thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left. </span> <span class=\"text Isa-30-22\" id=\"en-AKJV-18240\"><sup class=\"versenum\">22\u00a0</sup>Ye shall defile also the covering of thy graven images of silver, and the ornament of thy molten images of gold: thou shalt cast them away as a menstruous cloth; thou shalt say unto it, Get thee hence. </span> <span class=\"text Isa-30-23\" id=\"en-AKJV-18241\"><sup class=\"versenum\">23\u00a0</sup>Then shall he give the rain of thy seed, that thou shalt sow the ground withal; and bread of the increase of the earth, and it shall be fat and plenteous: in that day shall thy cattle feed in large pastures. </span> <span class=\"text Isa-30-24\" id=\"en-AKJV-18242\"><sup class=\"versenum\">24\u00a0</sup>The oxen likewise and the young asses that ear the ground shall eat clean provender, which hath been winnowed with the shovel and with the fan. </span> <span class=\"text Isa-30-25\" id=\"en-AKJV-18243\"><sup class=\"versenum\">25\u00a0</sup>And there shall be upon every high mountain, and upon every high hill, rivers and streams of waters in the day of the great slaughter, when the towers fall. </span> <span class=\"text Isa-30-26\" id=\"en-AKJV-18244\"><sup class=\"versenum\">26\u00a0</sup>Moreover the light of the moon shall be as the light of the sun, and the light of the sun shall be sevenfold, as the light of seven days, in the day that the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> bindeth up the breach of his people, and healeth the stroke of their wound.</span></p><span data-line-id='firstreading_533c1ac0-d022-588f-8593-9f043e2d0ff0'></span> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-30-27\" id=\"en-AKJV-18245\"><sup class=\"versenum\">27\u00a0</sup>Behold, the name of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> cometh from far,</span><br/><span class=\"text Isa-30-27\">burning with his anger,</span><br/><span class=\"text Isa-30-27\">and the burden thereof is heavy:</span><br/><span class=\"text Isa-30-27\">his lips are full of indignation,</span><br/><span class=\"text Isa-30-27\">and his tongue as a devouring fire:</span><br/><span class=\"text Isa-30-28\" id=\"en-AKJV-18246\"><sup class=\"versenum\">28\u00a0</sup>and his breath, as an overflowing stream,</span><br/><span class=\"text Isa-30-28\">shall reach to the midst of the neck,</span><br/><span class=\"text Isa-30-28\">to sift the nations with the sieve of vanity:</span><br/><span class=\"text Isa-30-28\">and there shall be a bridle in the jaws of the people,</span><br/><span class=\"text Isa-30-28\">causing them to err.</span><br/><span class=\"text Isa-30-29\" id=\"en-AKJV-18247\"><sup class=\"versenum\">29\u00a0</sup>Ye shall have a song,</span><br/><span class=\"text Isa-30-29\">as in the night when a holy solemnity is kept;</span><br/><span class=\"text Isa-30-29\">and gladness of heart,</span><br/><span class=\"text Isa-30-29\">as when one goeth with a pipe to come into the mountain of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>,</span><br/><span class=\"text Isa-30-29\">to the mighty One of Israel.</span><br/><span class=\"text Isa-30-30\" id=\"en-AKJV-18248\"><sup class=\"versenum\">30\u00a0</sup>And the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> shall cause his glorious voice to be heard,</span><br/><span class=\"text Isa-30-30\">and shall shew the lighting down of his arm,</span><br/><span class=\"text Isa-30-30\">with the indignation of his anger,</span><br/><span class=\"text Isa-30-30\">and with the flame of a devouring fire,</span><br/><span class=\"text Isa-30-30\">with scattering, and tempest, and hailstones.</span><br/><span class=\"text Isa-30-31\" id=\"en-AKJV-18249\"><sup class=\"versenum\">31\u00a0</sup>For through the voice of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> shall the Assyrian be beaten down,</span><br/><span class=\"text Isa-30-31\">which smote with a rod.</span><br/><span class=\"text Isa-30-32\" id=\"en-AKJV-18250\"><sup class=\"versenum\">32\u00a0</sup>And in every place where the grounded staff shall pass,</span><br/><span class=\"text Isa-30-32\">which the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> shall lay upon him,</span><br/><span class=\"text Isa-30-32\">it shall be with tabrets and harps:</span><br/><span class=\"text Isa-30-32\">and in battles of shaking will he fight with it.</span><br/><span class=\"text Isa-30-33\" id=\"en-AKJV-18251\"><sup class=\"versenum\">33\u00a0</sup>For Tophet is ordained of old;</span><br/><span class=\"text Isa-30-33\">yea, for the king it is prepared;</span><br/><span class=\"text Isa-30-33\">he hath made it deep and large:</span><br/><span class=\"text Isa-30-33\">the pile thereof is fire and much wood;</span><br/><span class=\"text Isa-30-33\">the breath of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>, like a stream of brimstone,</span><br/><span class=\"text Isa-30-33\">doth kindle it.</span></p></div> </div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"MAGNIFICAT"},{"line_type":"subheading","content":"The Song of Mary"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"My soul magnifies the Lord, *"},{"line_type":"congregation","content":"and my spirit rejoices in God my Savior;"},{"line_type":"congregation","content":"For he has regarded *"},{"line_type":"congregation","content":"the lowliness of his handmaiden."},{"line_type":"congregation","content":"For behold, from now on, *"},{"line_type":"congregation","content":"all generations will call me blessed;"},{"line_type":"congregation","content":"For he that is mighty has magnified me, *"},{"line_type":"congregation","content":"and holy is his Name."},{"line_type":"congregation","content":"And his mercy is on those who fear him, *"},{"line_type":"congregation","content":"throughout all generations."},{"line_type":"congregation","content":"He has shown the strength of his arm; *"},{"line_type":"congregation","content":"he has scattered the proud in the imagination of their hearts."},{"line_type":"congregation","content":"He has brought down the mighty from their thrones, *"},{"line_type":"congregation","content":"and has exalted the humble and meek."},{"line_type":"congregation","content":"He has filled the hungry with good things, *"},{"line_type":"congregation","content":"and the rich he has sent empty away."},{"line_type":"congregation","content":"He, remembering his mercy, has helped his servant Israel, *"},{"line_type":"congregation","content":"as he promised to our fathers, Abraham and his seed for ever."},{"line_type":"citation","content":"LUKE 1:46-55"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Luke 3:1-22"},{"line_type":"reader","content":"A reading from the Gospel of our Lord Jesus Christ according to St. Luke, beginning with the third chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_49f0c261-334d-53b9-92ac-63ffdf6ad629'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p class=\"top-1 chapter-1\"><span class=\"text Luke-3-1\" id=\"en-AKJV-25027\"><span class=\"chapternum\">3\u00a0</span>Now in the fifteenth year of the reign of Tiberius C\u00e6sar, Pontius Pilate being governor of Jud\u00e6a, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of Itur\u00e6a and of the region of Trachonitis, and Lysanias the tetrarch of Abilene, </span> <span class=\"text Luke-3-2\" id=\"en-AKJV-25028\"><sup class=\"versenum\">2\u00a0</sup>Annas and Caiaphas being the high priests, the word of God came unto John the son of Zacharias in the wilderness. </span> <span class=\"text Luke-3-3\" id=\"en-AKJV-25029\"><sup class=\"versenum\">3\u00a0</sup>And he came into all the country about Jordan, preaching the baptism of repentance for the remission of sins; </span> <span class=\"text Luke-3-4\" id=\"en-AKJV-25030\"><sup class=\"versenum\">4\u00a0</sup>as it is written in the book of the words of Esaias the prophet, saying, The voice of one crying in the wilderness, Prepare ye the way of the Lord, make his paths straight. </span> <span class=\"text Luke-3-5\" id=\"en-AKJV-25031\"><sup class=\"versenum\">5\u00a0</sup>Every valley shall be filled, and every mountain and hill shall be brought low; and the crooked shall be made straight, and the rough ways shall be made smooth; </span> <span class=\"text Luke-3-6\" id=\"en-AKJV-25032\"><sup class=\"versenum\">6\u00a0</sup>and all flesh shall see the salvation of God.</span></p><span data-line-id='secondreading_1c5fcf90-564a-5bdc-8da1-52ffead210f1'></span> <p><span class=\"text Luke-3-7\" id=\"en-AKJV-25033\"><sup class=\"versenum\">7\u00a0</sup>Then said he to the multitude that came forth to be baptized of him, O generation of vipers, who hath warned you to flee from the wrath to come? </span> <span class=\"text Luke-3-8\" id=\"en-AKJV-25034\"><sup class=\"versenum\">8\u00a0</sup>Bring forth therefore fruits worthy of repentance, and begin not to say within yourselves, We have Abraham to our father: for I say unto you, That God is able of these stones to raise up children unto Abraham. </span> <span class=\"text Luke-3-9\" id=\"en-AKJV-25035\"><sup class=\"versenum\">9\u00a0</sup>And now also the axe is laid unto the root of the trees: every tree therefore which bringeth not forth good fruit is hewn down, and cast into the fire.</span></p><span data-line-id='secondreading_37bb2fc8-e3a2-51b4-a2ec-93f1ed729925'></span> <p><span class=\"text Luke-3-10\" id=\"en-AKJV-25036\"><sup class=\"versenum\">10\u00a0</sup>And the people asked him, saying, What shall we do then? </span> <span class=\"text Luke-3-11\" id=\"en-AKJV-25037\"><sup class=\"versenum\">11\u00a0</sup>He answereth and saith unto them, He that hath two coats, let him impart to him that hath none; and he that hath meat, let him do likewise. </span> <span class=\"text Luke-3-12\" id=\"en-AKJV-25038\"><sup class=\"versenum\">12\u00a0</sup>Then came also publicans to be baptized, and said unto him, Master, what shall we do? </span> <span class=\"text Luke-3-13\" id=\"en-AKJV-25039\"><sup class=\"versenum\">13\u00a0</sup>And he said unto them, Exact no more than that which is appointed you. </span> <span class=\"text Luke-3-14\" id=\"en-AKJV-25040\"><sup class=\"versenum\">14\u00a0</sup>And the soldiers likewise demanded of him, saying, And what shall we do? And he said unto them, Do violence to no man, neither accuse any falsely; and be content with your wages.</span></p><span data-line-id='secondreading_c2c9e03f-f177-57c8-8191-27d8670f1f35'></span> <p><span class=\"text Luke-3-15\" id=\"en-AKJV-25041\"><sup class=\"versenum\">15\u00a0</sup>And as the people were in expectation, and all men mused in their hearts of John, whether he were the Christ, or not; </span> <span class=\"text Luke-3-16\" id=\"en-AKJV-25042\"><sup class=\"versenum\">16\u00a0</sup>John answered, saying unto them all, I indeed baptize you with water; but one mightier than I cometh, the latchet of whose shoes I am not worthy to unloose: he shall baptize you with the Holy Ghost and with fire: </span> <span class=\"text Luke-3-17\" id=\"en-AKJV-25043\"><sup class=\"versenum\">17\u00a0</sup>whose fan is in his hand, and he will throughly purge his floor, and will gather the wheat into his garner; but the chaff he will burn with fire unquenchable.</span></p><span data-line-id='secondreading_71f0e559-9708-55d8-927f-43591aff869e'></span> <p><span class=\"text Luke-3-18\" id=\"en-AKJV-25044\"><sup class=\"versenum\">18\u00a0</sup>And many other things in his exhortation preached he unto the people. </span> <span class=\"text Luke-3-19\" id=\"en-AKJV-25045\"><sup class=\"versenum\">19\u00a0</sup>But Herod the tetrarch, being reproved by him for Herodias his brother Philip\u2019s wife, and for all the evils which Herod had done, </span> <span class=\"text Luke-3-20\" id=\"en-AKJV-25046\"><sup class=\"versenum\">20\u00a0</sup>added yet this above all, that he shut up John in prison.</span></p><span data-line-id='secondreading_60364a69-3217-5134-b025-03e4f7413702'></span> <p><span class=\"text Luke-3-21\" id=\"en-AKJV-25047\"><sup class=\"versenum\">21\u00a0</sup>Now when all the people were baptized, it came to pass, that Jesus also being baptized, and praying, the heaven was opened, </span> <span class=\"text Luke-3-22\" id=\"en-AKJV-25048\"><sup class=\"versenum\">22\u00a0</sup>and the Holy Ghost descended in a bodily shape like a dove upon him, and a voice came from heaven, which said, Thou art my beloved Son; in thee I am well pleased.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"NUNC DIMITTIS"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"citation","content":"LUKE 2:29-32"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"That this evening may be holy, good, and peaceful,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That your holy angels may lead us in paths of peace and goodwill,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That we may be pardoned and forgiven for our sins and offenses,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That there may be peace in your Church and in the whole world,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That we may depart this life in your faith and fear, and not be condemned before the great judgment seat of Christ,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."},{"line_type":"leader_dialogue","content":"That we may be bound together by your Holy Spirit in the communion of the Blessed Virgin Mary, Hugh of Lincoln, and all your saints, entrusting one another and all our life to Christ,"},{"line_type":"congregation_dialogue","content":"We entreat you, O Lord."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Tuesday after the Twenty-fifth Sunday after Pentecost, or the Twenty-fourth Sunday after Trinity (Proper 28)"},{"line_type":"leader","content":"Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Hugh, Bishop of Lincoln and Renewer of Society, 1200"},{"line_type":"leader","content":"O God, our heavenly Father, you raised up your faithful servant Hugh of Lincoln to be Bishop and pastor in your Church and to feed your flock: Give abundantly to all pastors the gifts of your Holy Spirit, that they may minister in your household as true servants of Christ and stewards of your divine mysteries; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Aid against Perils"},{"line_type":"subheading","content":"Tuesday"},{"line_type":"leader","content":"Lighten our darkness, we beseech you, O Lord; and by your great mercy defend us from all perils and dangers of this night; for the love of your only Son, our Savior Jesus Christ."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"O God and Father of all, whom the whole heavens adore: Let the whole earth also worship you, all nations obey you, all tongues confess and bless you, and men, women, and children everywhere love you and serve you in peace; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Glory to God whose power, working in us, can do infinitely more than we can ask or imagine: Glory to him from generation to generation in the Church, and in Christ Jesus for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"EPHESIANS 3:20-21"}]}],"compline":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"rubric","content":"The Officiant begins:"},{"line_type":"leader_dialogue","content":"The Lord Almighty grant us a peaceful night and a perfect end."},{"line_type":"congregation_dialogue","content":"Amen."},{"line_type":"leader_dialogue","content":"Our help is in the Name of the Lord;"},{"line_type":"congregation_dialogue","content":"The maker of heaven and earth."}]},{"name":"Confession","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant continues"},{"line_type":"leader_dialogue","content":"Let us humbly confess our sins unto Almighty God."},{"line_type":"rubric","content":"Silence may be kept. The Officiant and People then say"},{"line_type":"congregation","content":"Almighty God and Father, we confess to you,"},{"line_type":"congregation","content":"to one another, and to the whole company of heaven,"},{"line_type":"congregation","content":"that we have sinned, through our own fault,"},{"line_type":"congregation","content":"in thought, and word, and deed, and in what we have left undone."},{"line_type":"congregation","content":"For the sake of your Son our Lord Jesus Christ,"},{"line_type":"congregation","content":"have mercy upon us, forgive us our sins,"},{"line_type":"congregation","content":"and by the power of your Holy Spirit,"},{"line_type":"congregation","content":"raise us up to serve you in newness of life,"},{"line_type":"congregation","content":"to the glory of your Name. Amen."},{"line_type":"rubric","content":"The Officiant alone says"},{"line_type":"leader","content":"May almighty God grant us forgiveness of all our sins, and the grace and comfort of the Holy Spirit."},{"line_type":"congregation","content":"Amen."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 4"},{"line_type":"subheading","content":"Cum invocarem"},{"line_type":"leader","content":"Hear me when I call, O God of my righteousness; *","preface":1},{"line_type":"leader","content":"you set me free when I was in trouble; have mercy upon me, and hear my prayer."},{"line_type":"congregation","content":"O you children of men, how long will you blaspheme my honor, *","preface":2},{"line_type":"congregation","content":"and have such pleasure in vanity, and seek after falsehood?"},{"line_type":"leader","content":"Know this also, that the L\u1d0f\u0280\u1d05 has chosen for himself the one that is godly; *","preface":3},{"line_type":"leader","content":"when I call upon the L\u1d0f\u0280\u1d05, he will hear me."},{"line_type":"congregation","content":"Stand in awe, and sin not; *","preface":4},{"line_type":"congregation","content":"commune with your own heart upon your bed, and be still."},{"line_type":"leader","content":"Offer the sacrifice of righteousness *","preface":5},{"line_type":"leader","content":"and put your trust in the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"There are many that say, \u201cWho will show us any good?\u201d *","preface":6},{"line_type":"congregation","content":"L\u1d0f\u0280\u1d05, lift up the light of your countenance upon us."},{"line_type":"leader","content":"You have put gladness in my heart, *","preface":7},{"line_type":"leader","content":"more than when others\u2019 grain and wine and oil increased."},{"line_type":"congregation","content":"I will lay me down in peace, and take my rest; *","preface":8},{"line_type":"congregation","content":"for you, L\u1d0f\u0280\u1d05, only, make me dwell in safety."},{"line_type":"heading","content":"Psalm 31:1-6"},{"line_type":"subheading","content":"In te, Domine, speravi"},{"line_type":"leader","content":"In you, O L\u1d0f\u0280\u1d05, have I put my trust; *","preface":1},{"line_type":"leader","content":"let me never be put to confusion; deliver me in your righteousness."},{"line_type":"congregation","content":"Bow down your ear to me, *","preface":2},{"line_type":"congregation","content":"make haste to deliver me,"},{"line_type":"leader","content":"And be my strong rock and house of defense, *","preface":3},{"line_type":"leader","content":"that you may save me."},{"line_type":"congregation","content":"For you are my strong rock and my castle; *","preface":4},{"line_type":"congregation","content":"be also my guide, and lead me for your Name\u2019s sake."},{"line_type":"leader","content":"Draw me out of the net that they have laid secretly for me, *","preface":5},{"line_type":"leader","content":"for you are my strength."},{"line_type":"congregation","content":"Into your hands I commend my spirit, *","preface":6},{"line_type":"congregation","content":"for you have redeemed me, O L\u1d0f\u0280\u1d05, O God of truth."},{"line_type":"heading","content":"Psalm 91"},{"line_type":"subheading","content":"Qui habitat"},{"line_type":"leader","content":"Whoever dwells under the defense of the Most High *","preface":1},{"line_type":"leader","content":"shall abide under the shadow of the Almighty."},{"line_type":"congregation","content":"I will say unto the L\u1d0f\u0280\u1d05, \u201cYou are my refuge and my stronghold, *","preface":2},{"line_type":"congregation","content":"my God in whom I will trust.\u201d"},{"line_type":"leader","content":"For he shall deliver you from the snare of the hunter *","preface":3},{"line_type":"leader","content":"and from the deadly pestilence."},{"line_type":"congregation","content":"He shall defend you under his wings, and you shall be safe under his feathers; *","preface":4},{"line_type":"congregation","content":"his faithfulness and truth shall be your shield and buckler."},{"line_type":"leader","content":"You shall not be afraid of any terror by night, *","preface":5},{"line_type":"leader","content":"nor of the arrow that flies by day,"},{"line_type":"congregation","content":"Of the pestilence that walks in darkness, *","preface":6},{"line_type":"congregation","content":"nor of the sickness that destroys at noonday."},{"line_type":"leader","content":"A thousand shall fall beside you, and ten thousand at your right hand, *","preface":7},{"line_type":"leader","content":"but it shall not come near you."},{"line_type":"congregation","content":"Indeed, with your eyes you shall behold *","preface":8},{"line_type":"congregation","content":"and see the reward of the ungodly."},{"line_type":"leader","content":"Because you have said, \u201cThe L\u1d0f\u0280\u1d05 is my refuge,\u201d *","preface":9},{"line_type":"leader","content":"and have made the Most High your stronghold,"},{"line_type":"congregation","content":"There shall no evil happen to you, *","preface":10},{"line_type":"congregation","content":"neither shall any plague come near your dwelling."},{"line_type":"leader","content":"For he shall give his angels charge over you, *","preface":11},{"line_type":"leader","content":"to keep you in all your ways."},{"line_type":"congregation","content":"They shall bear you in their hands, *","preface":12},{"line_type":"congregation","content":"that you hurt not your foot against a stone."},{"line_type":"leader","content":"You shall tread upon the lion and adder; *","preface":13},{"line_type":"leader","content":"the young lion and the serpent you shall trample under your feet."},{"line_type":"congregation","content":"\u201cBecause he has set his love upon me, therefore I will deliver him; *","preface":14},{"line_type":"congregation","content":"I will lift him up, because he has known my Name."},{"line_type":"leader","content":"He shall call upon me, and I will hear him; *","preface":15},{"line_type":"leader","content":"indeed, I am with him in trouble; I will deliver him and bring him honor."},{"line_type":"congregation","content":"With long life I will satisfy him, *","preface":16},{"line_type":"congregation","content":"and show him my salvation.\u201d"},{"line_type":"heading","content":"Psalm 134"},{"line_type":"subheading","content":"Ecce nunc"},{"line_type":"leader","content":"Behold now, praise the L\u1d0f\u0280\u1d05, *","preface":1},{"line_type":"leader","content":"all you servants of the L\u1d0f\u0280\u1d05,"},{"line_type":"congregation","content":"You that stand by night in the house of the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"even in the courts of the house of our God."},{"line_type":"leader","content":"Lift up your hands in the sanctuary *","preface":3},{"line_type":"leader","content":"and sing praises unto the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 who made heaven and earth *","preface":4},{"line_type":"congregation","content":"give you blessing out of Zion."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"Come to me, all who labor and are heavy laden, and I will give you rest. Take my yoke upon you, and learn from me, for I am gentle and lowly in heart, and you will find rest for your souls. For my yoke is easy, and my burden is light."},{"line_type":"citation","content":"MATTHEW 11:28-30"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"Into your hands, O Lord, I commend my spirit;"},{"line_type":"congregation_dialogue","content":"For you have redeemed me, O Lord, O God of truth."},{"line_type":"leader_dialogue","content":"Keep me, O Lord, as the apple of your eye;"},{"line_type":"congregation_dialogue","content":"Hide me under the shadow of your wings."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Visit this place, O Lord, and drive far from it all snares of the enemy; let your holy angels dwell with us to preserve us in peace; and let your blessing be upon us always; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Be present, O merciful God, and protect us through the hours of this night, so that we who are wearied by the changes and chances of this life may rest in your eternal changelessness; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Mission"},{"line_type":"leader","content":"Keep watch, dear Lord, with those who work, or watch, or weep this night, and give your angels charge over those who sleep. Tend the sick, Lord Christ; give rest to the weary, bless the dying, soothe the suffering, pity the afflicted, shield the joyous; and all for your love\u2019s sake."},{"line_type":"congregation","content":"Amen."}]},{"name":"Nunc Dimittis","lines":[{"line_type":"heading","content":"Nunc Dimittis"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The Officiant and People say or sing the Song of Simeon with this Antiphon, all standing"},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader_dialogue","content":"The almighty and merciful Lord, Father, Son, and Holy Spirit, bless us and keep us, this night and evermore."},{"line_type":"congregation_dialogue","content":"Amen."}]}]}};
